rule.script:
%Script(name:="Housekeeping",application:="NetSuite",plantype:="Plan")

/* Aggregating (Employee, Department, Subsidiary) Dimensions */
FIX(&FcstYr1:&FcstYr2, @RELATIVE("YearTotal",0), @RELATIVE("TotalComp",0), @RELATIVE("TotalHC",0) &CurrentScenario, Actual, &CurrentVersion, No_Location )

   AGG(Employee);
   Agg(Department);
   AGG(Subsidiary);

ENDFIX

component.script:
/* Housekeeping */
SET AGGMISSG ON;
SET UPDATECALC OFF;
SET EMPTYMEMBERSETS ON;
